import{_ as t,o as d,c as o,ag as a}from"./chunks/framework.TQKaXlFR.js";const m=JSON.parse('{"title":"组件与状态工具选择","description":"","frontmatter":{},"headers":[],"relativePath":"components/overview.md","filePath":"components/overview.md"}'),r={name:"components/overview.md"};function c(n,e,s,i,p,l){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="组件与状态工具选择" tabindex="-1">组件与状态工具选择 <a class="header-anchor" href="#组件与状态工具选择" aria-label="Permalink to &quot;组件与状态工具选择&quot;">​</a></h1><p>本项目的组件参考以当前Element Plus应用适配为准。适用于新增或维护后台页面的前端开发者；需了解Vue3、TypeScript和项目 <code>#/</code> 导入别名。现存业务页并未全部统一为VXE或Vben Schema Form，不能直接照搬上游最新版本API。</p><h2 id="按问题选择" tabindex="-1">按问题选择 <a class="header-anchor" href="#按问题选择" aria-label="Permalink to &quot;按问题选择&quot;">​</a></h2><table tabindex="0"><thead><tr><th>需求</th><th>当前可复用入口</th><th>注意事项</th></tr></thead><tbody><tr><td>分页/排序/刷新</td><td><code>usePagedList</code></td><td>接收records/total；items响应先显式转换</td></tr><tr><td>新增/编辑/只读详情</td><td><code>useEntityDialog</code></td><td>由调用方提供真实读取、保存与校验</td></tr><tr><td>危险动作确认</td><td><code>useConfirmedAction</code></td><td>allowed和busy只是前端防护，后端仍鉴权</td></tr><tr><td>业务字典</td><td><code>useDictionary</code></td><td>启用选项与历史标签分开读取</td></tr><tr><td>轻量帮助</td><td><code>PageHint</code></td><td>title必需、details可选，可关闭、可展开</td></tr><tr><td>Schema表单</td><td><code>#/adapter/form</code>的<code>useVbenForm</code></td><td>使用本地组件映射及规则</td></tr><tr><td>高级表格</td><td><code>#/adapter/vxe-table</code>的<code>useVbenVxeGrid</code></td><td>默认结果字段items，业务records需要适配</td></tr><tr><td>Modal / Drawer</td><td><code>@vben/common-ui</code></td><td>API和返回组件成对使用</td></tr><tr><td>文件上传</td><td><code>#/api/system/file</code></td><td>真实受保护上传，不是低代码附件字段</td></tr></tbody></table><h2 id="接入顺序与正常结果" tabindex="-1">接入顺序与正常结果 <a class="header-anchor" href="#接入顺序与正常结果" aria-label="Permalink to &quot;接入顺序与正常结果&quot;">​</a></h2><p>先确认页面权限与后端响应，再选择状态工具，最后绑定模板。把loading、error、empty、success分开呈现；查询失败不伪装成空列表。保存失败保持输入，详情态禁用写操作。小片段用于说明接口，静态数据示例不证明真实API成功。</p><p>遇到组件未注册先检查 <code>apps/web-ele/src/adapter/component/index.ts</code>；遇到响应字段不匹配检查适配，而不是修改共享组件给单个页面兜底。前端TypeScript契约不能替代后端字段、权限和租户校验。</p><h2 id="源码与参考方式" tabindex="-1">源码与参考方式 <a class="header-anchor" href="#源码与参考方式" aria-label="Permalink to &quot;源码与参考方式&quot;">​</a></h2><p>本地入口为 <code>apps/web-ele/src/composables/</code>、<code>apps/web-ele/src/components/page-hint.vue</code>、<code>apps/web-ele/src/adapter/</code>；上游封装实现位于 <code>packages/@core/ui-kit/</code>、<code>packages/effects/common-ui/</code>、<code>packages/effects/plugins/</code>。</p><p>分类方式参考<a href="https://doc.vben.pro/guide/introduction/vben.html" target="_blank" rel="noreferrer">Vben官方文档</a>、<a href="https://github.com/pure-admin/pure-admin-doc" target="_blank" rel="noreferrer">Pure文档源码</a>和<a href="https://help.jeecg.com/" target="_blank" rel="noreferrer">Jeecg文档中心</a>。参数和示例来自本地源码，没有把它们的产品能力或版本承诺移植到本项目。</p>',10)])])}const u=t(r,[["render",c]]);export{m as __pageData,u as default};
